WITH exploded AS (SELECT id, coupon_codes, elem.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) e AS elem) SELECT promo, COUNT_IF(promo = 'VIP') AS vip_events, COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END) AS welcome5_count, SORT_ARRAY(COLLECT_SET(promo)) AS promo_list, COUNT(*) AS cnt, COUNT(DISTINCT promo) AS distinct_promos, COUNT(DISTINCT id) AS distinct_ids FROM exploded GROUP BY 1 ORDER BY welcome5_count DESC NULLS FIRST;
